-- ====================================================================
-- DMF0082 UICATEGORY — SCM_ADM_PROC_M 재구성 (클라우드용, 사내 실측 literal 덤프 2026-08-07)
--   GET/CURRENT = IN 16(+projectCode/owner/senderCode 14~16) + OUT 6(17~22)
--   SAVE_MAIN_DATA = 18행 (2026-08-05 asFromSite IN17 + o_result_cursor 18 — 클라우드 미이관분 포함)
--   DELETE→INSERT (PROC 3종 한정). 감사 = 'admin'. ⚠️ QA·DEV 2곳 동시 적용 의무
-- ====================================================================

-- PKG_DMF0082.P_DMF0082_GET_MAIN_DATA (22행)
DELETE FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0082.P_DMF0082_GET_MAIN_DATA';

-- PKG_DMF0082.P_DMF0082_GET_MAIN_DATA_CURRENT (22행)
DELETE FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0082.P_DMF0082_GET_MAIN_DATA_CURRENT';

-- PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA (18행)
DELETE FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA';

COMMIT;

-- [검증] 기대: GET 22 / CURRENT 22 / SAVE 18
SELECT PROC_NM, COUNT(*) CNT FROM SCM_MGR.SCM_ADM_PROC_M
WHERE PROC_NM IN ('PKG_DMF0082.P_DMF0082_GET_MAIN_DATA','PKG_DMF0082.P_DMF0082_GET_MAIN_DATA_CURRENT','PKG_DMF0082.P_DMF0082_SAVE_MAIN_DATA')
GROUP BY PROC_NM ORDER BY 1;
